using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Text;
using System.Windows.Forms;

namespace AgitCon {
    // Bitmap/DIB, not CF_HDROP. No foreign window messages or key injection.
    public sealed class ImageClipboard:IDisposable {
        public readonly DataObject Data=new DataObject();
        readonly Bitmap bitmap;readonly MemoryStream png=new MemoryStream(),dib;
        public ImageClipboard(Image source){if(ImageBundle.Animated(source))throw new Exception("움직이는 콘은 이미지 클립보드로 정지시키지 않아요. 원본 파일 복사를 사용해주세요.");
            bitmap=PixelCopy(source,false);
            // Normalize metadata as well as pixels, so every clipboard representation agrees.
            using(var transparent=PixelCopy(source,true))transparent.Save(png,ImageFormat.Png);png.Position=0;
            using(var bmp=new MemoryStream()){bitmap.Save(bmp,ImageFormat.Bmp);byte[] bytes=bmp.ToArray();dib=new MemoryStream(bytes,14,bytes.Length-14,false,true);}
            Data.SetData(DataFormats.Dib,false,dib);Data.SetData(DataFormats.Bitmap,true,bitmap);Data.SetData("PNG",false,png);
        }
        internal static Bitmap PixelCopy(Image source,bool alpha){var result=new Bitmap(source.Width,source.Height,alpha?PixelFormat.Format32bppArgb:PixelFormat.Format24bppRgb);result.SetResolution(96,96);using(var graphics=Graphics.FromImage(result)){graphics.PageUnit=GraphicsUnit.Pixel;graphics.Clear(alpha?Color.Transparent:Color.White);graphics.CompositingMode=alpha?System.Drawing.Drawing2D.CompositingMode.SourceCopy:System.Drawing.Drawing2D.CompositingMode.SourceOver;graphics.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.NearestNeighbor;graphics.PixelOffsetMode=System.Drawing.Drawing2D.PixelOffsetMode.Half;graphics.DrawImage(source,new Rectangle(0,0,source.Width,source.Height),0,0,source.Width,source.Height,GraphicsUnit.Pixel);}return result;}
        internal static void TestFiles(string[] paths){string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"image-clipboard-files-test.txt");try{var lines=new System.Collections.Generic.List<string>();foreach(string path in paths)using(var source=new Bitmap(path))using(var payload=new ImageClipboard(source)){var copied=(Bitmap)payload.Data.GetData(DataFormats.Bitmap,false);int opaque=0;for(int y=0;y<source.Height;y++)for(int x=0;x<source.Width;x++){var c=source.GetPixel(x,y);if(c.A==255){opaque++;if(c.ToArgb()!=copied.GetPixel(x,y).ToArgb())throw new Exception("Opaque source pixel changed");}}if(source.Size!=copied.Size)throw new Exception("Changed dimensions");lines.Add(Path.GetFileName(path)+": "+source.Width+"x"+source.Height+"; DPI "+source.HorizontalResolution+"x"+source.VerticalResolution+"; "+opaque+" opaque pixels preserved");}File.WriteAllText(report,"PASS: actual local source files, no clipboard/Kakao interaction.\r\n"+String.Join("\r\n",lines));}catch(Exception ex){File.WriteAllText(report,"FAIL: "+ex);Environment.ExitCode=1;}}
        public static bool Put(string preview){using(var image=Image.FromFile(preview)){if(ImageBundle.Animated(image))return false;using(var payload=new ImageClipboard(image))Clipboard.SetDataObject(payload.Data,true,5,80);}return true;}
        public void Dispose(){bitmap.Dispose();png.Dispose();dib.Dispose();}
        public static void Test(){string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"image-clipboard-test.txt");try{int checks=0;foreach(var dpi in new[]{new SizeF(72,72),new SizeF(96,96),new SizeF(144,144),new SizeF(288.0106f,288.0106f),new SizeF(300,300),new SizeF(72,144),new SizeF(300,72)})using(var source=new Bitmap(41,29,PixelFormat.Format32bppArgb)){source.SetResolution(dpi.Width,dpi.Height);for(int y=0;y<source.Height;y++)for(int x=0;x<source.Width;x++)source.SetPixel(x,y,Color.FromArgb(255,(x*17)%256,(y*23)%256,((x+y)*11)%256));source.SetPixel(10,10,Color.Transparent);source.SetPixel(11,10,Color.FromArgb(128,127,63,191));using(var payload=new ImageClipboard(source)){if(payload.Data.GetDataPresent(DataFormats.FileDrop,false))throw new Exception("FileDrop in image payload");var copied=(Bitmap)payload.Data.GetData(DataFormats.Bitmap,false);if(copied.Width!=source.Width||copied.Height!=source.Height)throw new Exception("Bitmap dimensions");var stream=(MemoryStream)payload.Data.GetData(DataFormats.Dib,false);byte[] dibBytes=stream.ToArray();byte[] bmpBytes=new byte[dibBytes.Length+14];using(var header=new BinaryWriter(new MemoryStream(bmpBytes))){header.Write((ushort)0x4D42);header.Write(bmpBytes.Length);header.Write(0);header.Write(14+40);}Buffer.BlockCopy(dibBytes,0,bmpBytes,14,dibBytes.Length);using(var dibImage=new Bitmap(new MemoryStream(bmpBytes)))using(var pngImage=new Bitmap(new MemoryStream(((MemoryStream)payload.Data.GetData("PNG",false)).ToArray()))){if(dibImage.Size!=source.Size||pngImage.Size!=source.Size)throw new Exception("Encoded dimensions");for(int y=0;y<source.Height;y++)for(int x=0;x<source.Width;x++){var expected=source.GetPixel(x,y);var white=Color.FromArgb(255,(expected.R*expected.A+255*(255-expected.A)+127)/255,(expected.G*expected.A+255*(255-expected.A)+127)/255,(expected.B*expected.A+255*(255-expected.A)+127)/255);Func<Color,Color,bool> equal=(a,b)=>a.A==b.A&&Math.Abs(a.R-b.R)<=1&&Math.Abs(a.G-b.G)<=1&&Math.Abs(a.B-b.B)<=1;if(!equal(copied.GetPixel(x,y),white)||!equal(dibImage.GetPixel(x,y),white))throw new Exception("Bitmap/DIB pixel changed at "+x+","+y+"; source DPI="+dpi);if(pngImage.GetPixel(x,y).A!=expected.A||(expected.A!=0&&!equal(pngImage.GetPixel(x,y),expected)))throw new Exception("PNG pixel changed");checks++;}}if(source.HorizontalResolution!=dpi.Width||source.VerticalResolution!=dpi.Height)throw new Exception("Source DPI changed");}}
            File.WriteAllText(report,"PASS: "+checks+" source/Bitmap/DIB/PNG pixel comparisons across 72/96/144/288/300 and unequal XY DPI; complete edges, non-square dimensions, white alpha fallback, transparent PNG, source DPI preserved. No system clipboard, Kakao, input or send.");}catch(Exception ex){File.WriteAllText(report,"FAIL: "+ex);Environment.ExitCode=1;}}

    }
    // Animated stickers must use a file payload; bitmap clipboard formats flatten them.
    static class GifAttachment {
        [DllImport("shell32.dll",CharSet=CharSet.Unicode)]static extern uint DragQueryFile(IntPtr drop,uint index,StringBuilder name,uint size);
        [DllImport("kernel32.dll")]static extern IntPtr GlobalLock(IntPtr memory);
        [DllImport("kernel32.dll")]static extern bool GlobalUnlock(IntPtr memory);
        [DllImport("ole32.dll")]static extern void ReleaseStgMedium(ref System.Runtime.InteropServices.ComTypes.STGMEDIUM medium);
        static void CheckNativePayload(DataObject payload,string path){
            var native=(System.Runtime.InteropServices.ComTypes.IDataObject)payload;
            var format=new System.Runtime.InteropServices.ComTypes.FORMATETC{cfFormat=15,dwAspect=System.Runtime.InteropServices.ComTypes.DVASPECT.DVASPECT_CONTENT,lindex=-1,tymed=System.Runtime.InteropServices.ComTypes.TYMED.TYMED_HGLOBAL};
            System.Runtime.InteropServices.ComTypes.STGMEDIUM data;native.GetData(ref format,out data);
            try{if(data.tymed!=System.Runtime.InteropServices.ComTypes.TYMED.TYMED_HGLOBAL||DragQueryFile(data.unionmember,UInt32.MaxValue,null,0)!=1)throw new Exception("Native CF_HDROP count/type");var name=new StringBuilder(path.Length+1);DragQueryFile(data.unionmember,0,name,(uint)name.Capacity);if(name.ToString()!=path)throw new Exception("Native Unicode GIF path mismatch");IntPtr locked=GlobalLock(data.unionmember);if(locked==IntPtr.Zero)throw new Exception("Invalid DROPFILES memory");try{int offset=Marshal.ReadInt32(locked);if(offset<20||Marshal.ReadInt32(locked,16)==0||Marshal.ReadInt16(locked,offset+path.Length*2)!=0||Marshal.ReadInt16(locked,offset+(path.Length+1)*2)!=0)throw new Exception("DROPFILES offset="+offset+" wide="+Marshal.ReadInt32(locked,16)+" end="+Marshal.ReadInt16(locked,offset+path.Length*2)+","+Marshal.ReadInt16(locked,offset+(path.Length+1)*2));}finally{GlobalUnlock(data.unionmember);}}finally{ReleaseStgMedium(ref data);}
            format.cfFormat=(short)DataFormats.GetFormat("Preferred DropEffect").Id;native.GetData(ref format,out data);try{IntPtr locked=GlobalLock(data.unionmember);if(locked==IntPtr.Zero)throw new Exception("Invalid drop effect memory");try{if(Marshal.ReadInt32(locked)!=1)throw new Exception("File operation must be COPY");}finally{GlobalUnlock(data.unionmember);}}finally{ReleaseStgMedium(ref data);}
        }
        internal static string Describe(string path,bool imageData=true){if(!imageData)return Path.GetExtension(path).TrimStart('.').ToUpperInvariant()+" · 파일 복사";using(var image=Image.FromFile(path)){int frames=image.FrameDimensionsList.Select(id=>image.GetFrameCount(new FrameDimension(id))).DefaultIfEmpty(1).Max();string format=image.RawFormat.Guid==ImageFormat.Gif.Guid?"GIF":image.RawFormat.Guid==ImageFormat.Png.Guid?"PNG":image.RawFormat.Guid==ImageFormat.Jpeg.Guid?"JPEG":Path.GetExtension(path).TrimStart('.').ToUpperInvariant();return format+" · "+image.Width+"×"+image.Height+" · "+frames+"프레임";}}
        internal static bool AnimatedGif(string path){if(!String.Equals(Path.GetExtension(path),".gif",StringComparison.OrdinalIgnoreCase))return false;using(var image=Image.FromFile(path))return ImageBundle.Animated(image);}
        internal static DataObject FilePayload(string path){if(!AnimatedGif(path))throw new InvalidDataException("Expected an animated GIF");var files=new System.Collections.Specialized.StringCollection();files.Add(Path.GetFullPath(path));var data=new DataObject();data.SetFileDropList(files);data.SetData("Preferred DropEffect",false,new MemoryStream(BitConverter.GetBytes(1u)));return data;}
        internal static DataObject WebpPayload(string path){var bytes=File.ReadAllBytes(path);if(bytes.Length<12||System.Text.Encoding.ASCII.GetString(bytes,0,4)!="RIFF"||System.Text.Encoding.ASCII.GetString(bytes,8,4)!="WEBP"||BitConverter.ToUInt32(bytes,4)!=bytes.Length-8)throw new InvalidDataException("Expected WebP RIFF");int offset=12,frames=0;bool animation=false;while(offset+8<=bytes.Length){string tag=System.Text.Encoding.ASCII.GetString(bytes,offset,4);uint size=BitConverter.ToUInt32(bytes,offset+4);long end=(long)offset+8+size+(size&1);if(end>bytes.Length)throw new InvalidDataException("Invalid WebP chunk");if(tag=="ANIM")animation=true;if(tag=="ANMF")frames++;offset=(int)end;}if(offset!=bytes.Length||!animation||frames<2)throw new InvalidDataException("Expected animated WebP");var files=new System.Collections.Specialized.StringCollection();files.Add(Path.GetFullPath(path));var payload=new DataObject();payload.SetFileDropList(files);payload.SetData("Preferred DropEffect",false,new MemoryStream(BitConverter.GetBytes(1u)));payload.SetData("WebP",false,new MemoryStream(bytes,false));payload.SetData("image/webp",false,new MemoryStream(bytes,false));return payload;}
        internal static void TestWebp(){string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"webp-attachment-test.txt");try{string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-work","webp-attachment-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string source=Path.Combine(root,"움짤.gif");byte[] gif=new byte[]{71,73,70,56,57,97,1,0,1,0,128,0,0,0,0,0,255,255,255,33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,68,1,0,33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,76,1,0,59};File.WriteAllBytes(source,gif);string path=AssetCodec.AnimatedWebp(source,System.Threading.CancellationToken.None);var payload=WebpPayload(path);CheckNativePayload(payload,path);var stamp=File.GetLastWriteTimeUtc(path);if(AssetCodec.AnimatedWebp(source,System.Threading.CancellationToken.None)!=path||File.GetLastWriteTimeUtc(path)!=stamp||!File.ReadAllBytes(source).SequenceEqual(gif))throw new Exception("WebP cache/source preservation failed");foreach(string format in new[]{DataFormats.Bitmap,DataFormats.Dib,"PNG",DataFormats.UnicodeText})if(payload.GetDataPresent(format,false))throw new Exception("Flattening/text formats in WebP payload");if(!((MemoryStream)payload.GetData("WebP",false)).ToArray().SequenceEqual(File.ReadAllBytes(path))||!payload.GetDataPresent("image/webp",false))throw new Exception("Encoded WebP format mismatch");using(var canceled=new System.Threading.CancellationTokenSource()){canceled.Cancel();bool stopped=false;try{AssetCodec.AnimatedWebp(source,canceled.Token);}catch(OperationCanceledException){stopped=true;}if(!stopped)throw new Exception("Canceled conversion continued");}File.WriteAllText(report,"PASS: real GIF-to-animated-WebP conversion, RIFF/ANIM/ANMF validation, encoded WebP+image/webp and native CF_HDROP COPY, no bitmap/text flattening, cache reuse, original bytes preserved, cancellation. No system clipboard, windows, input or KakaoTalk interaction.\r\n");}catch(Exception ex){File.WriteAllText(report,"FAIL: "+ex);Environment.ExitCode=1;}}
        internal static bool PreviewEnabled(bool imageAction,bool animatedGif,bool copiedImage,bool enabled){return imageAction&&enabled&&(animatedGif||copiedImage);}
        internal static void Test(){string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"gif-attachment-test.txt");try{
            string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-work","gif-attachment-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string path=Path.Combine(root,"한글 움짤.gif");byte[] bytes=new byte[]{71,73,70,56,57,97,1,0,1,0,128,0,0,0,0,0,255,255,255,33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,68,1,0,33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,76,1,0,59};File.WriteAllBytes(path,bytes);var payload=FilePayload(path);CheckNativePayload(payload,path);
            if(payload.GetFileDropList().Count!=1||payload.GetFileDropList()[0]!=path)throw new Exception("GIF file payload mismatch");
            foreach(string format in new[]{DataFormats.Bitmap,DataFormats.Dib,"PNG",DataFormats.UnicodeText})if(payload.GetDataPresent(format,false))throw new Exception("Flattening/text clipboard format in GIF payload");
            using(var image=Image.FromFile(path))if(image.GetFrameCount(FrameDimension.Time)!=2)throw new Exception("GIF frames lost");
            string raw=Path.Combine(root,"original.webp");File.WriteAllBytes(raw,new byte[]{1});var entry=new Entry{Path=path,OriginalPath=raw};
            if(DcShop.EnsureAttachment(entry,System.Threading.CancellationToken.None,true)!=path||DcShop.EnsureAttachment(entry,System.Threading.CancellationToken.None,false)!=raw)throw new Exception("Compatible GIF/original WebP selection failed");
            if(!File.ReadAllBytes(path).SequenceEqual(bytes))throw new Exception("Source GIF modified");
            if(!Describe(raw,false).Contains("WEBP"))throw new Exception("Raw copy must not decode WebP");
            if(!Describe(path).Contains("GIF")||!Describe(path).Contains("2프레임"))throw new Exception("GIF format/frame diagnostics");
            if(!PreviewEnabled(true,true,false,true)||PreviewEnabled(false,true,false,true)||PreviewEnabled(true,true,false,false)||PreviewEnabled(true,false,false,true)||!PreviewEnabled(true,false,true,true))throw new Exception("Preview opt-in/copy-only policy failed");
            File.WriteAllText(report,"PASS: native CF_HDROP Unicode/double-NUL/header and Preferred DropEffect COPY verified through COM IDataObject; no bitmap/text formats; two source frames unchanged, compatible selection uses GIF over original WebP, copy-only actions and disabled preview never paste; static image preview preserved. In-memory DataObject only; no system clipboard, key injection or KakaoTalk interaction.\r\n");
        }catch(Exception ex){File.WriteAllText(report,"FAIL: "+ex);Environment.ExitCode=1;}}
    }

}
